// AgentServiceHandler is an implementation of the execenv.guest.v1.AgentService service.
type AgentServiceHandler interface {
	// Hello says what this helper serves. The host refuses a helper on
	// another protocol, or without the journal or the process log.
	Hello(context.Context, *connect.Request[v1.HelloRequest]) (*connect.Response[v1.HelloResponse], error)
	// Processes, by tag. The guest runs them inside the contained workload
	// and keeps the newest output of each stream by absolute offset; the host
	// keeps the longer history, grace and timeout.
	Spawn(context.Context, *connect.Request[v1.SpawnRequest]) (*connect.Response[v1.SpawnResponse], error)
	// ListProcesses describes every process the guest holds, so a restarted
	// host can adopt them.
	ListProcesses(context.Context, *connect.Request[v1.ListProcessesRequest]) (*connect.Response[v1.ListProcessesResponse], error)
	// Output streams the process's output from the given offsets, each chunk
	// with its stream and offset, then its exit. It opens with an empty event
	// as soon as the guest has the process.
	Output(context.Context, *connect.Request[v1.OutputRequest], *connect.ServerStream[v1.OutputResponse]) error
	// Feed carries input for one process. The first message names it.
	Feed(context.Context, *connect.ClientStream[v1.FeedRequest]) (*connect.Response[v1.FeedResponse], error)
	CloseFeed(context.Context, *connect.Request[v1.ProcessRef]) (*connect.Response[v1.Empty], error)
	ResizeProcess(context.Context, *connect.Request[v1.ResizeRequest]) (*connect.Response[v1.Empty], error)
	SignalProcess(context.Context, *connect.Request[v1.SignalRequest]) (*connect.Response[v1.Empty], error)
	// ProcessScreen is a terminal process's screen, from the helper's own
	// headless terminal fed every byte the process wrote.
	ProcessScreen(context.Context, *connect.Request[v1.ProcessScreenRequest]) (*connect.Response[v11.Screen], error)
	DialPort(context.Context, *connect.BidiStream[v11.PortFrame, v11.PortFrame]) error
	ListeningPorts(context.Context, *connect.Request[v1.Empty]) (*connect.Response[v11.ListeningPortsResponse], error)
	// Freeze closes I/O before the host pauses the machine; Thaw reopens it.
	Freeze(context.Context, *connect.Request[v1.FreezeRequest]) (*connect.Response[v1.FreezeResponse], error)
	Thaw(context.Context, *connect.Request[v1.ThawRequest]) (*connect.Response[v1.ThawResponse], error)
	// The workload's process log, kept in the guest until the host
	// acknowledges it. The host checks grant and epoch.
	ObserveProcesses(context.Context, *connect.Request[v11.ObserveProcessesRequest]) (*connect.Response[v11.ProcessPage], error)
	AcknowledgeProcesses(context.Context, *connect.Request[v11.AcknowledgeProcessesRequest]) (*connect.Response[v11.AcknowledgeProcessesResponse], error)
	UploadContent(context.Context, *connect.ClientStream[v11.UploadContentRequest]) (*connect.Response[v11.ContentReference], error)
	InitializeProjection(context.Context, *connect.Request[v11.InitializeProjectionRequest]) (*connect.Response[v11.ProjectionReceipt], error)
	ApplyProjection(context.Context, *connect.Request[v11.ApplyProjectionRequest]) (*connect.Response[v11.ProjectionReceipt], error)
	Observe(context.Context, *connect.Request[v11.ObserveRequest]) (*connect.Response[v11.ObservationPage], error)
	ReadObservationContent(context.Context, *connect.Request[v11.ReadObservationContentRequest], *connect.ServerStream[v11.ContentChunk]) error
	ConfirmObservationProjection(context.Context, *connect.Request[v11.ConfirmObservationProjectionRequest]) (*connect.Response[v11.ConfirmObservationProjectionResponse], error)
	AcknowledgeObservations(context.Context, *connect.Request[v11.AcknowledgeObservationsRequest]) (*connect.Response[v11.AcknowledgeObservationsResponse], error)
	// The plain file API over the workspace. The host checks grant and epoch;
	// changing calls still carry the fence the guest binds.
	Stat(context.Context, *connect.Request[v11.StatRequest]) (*connect.Response[v11.FileInfo], error)
	List(context.Context, *connect.Request[v11.ListRequest]) (*connect.Response[v11.ListResponse], error)
	ReadFile(context.Context, *connect.Request[v11.ReadFileRequest], *connect.ServerStream[v11.ContentChunk]) error
	WriteFile(context.Context, *connect.ClientStream[v11.WriteFileRequest]) (*connect.Response[v11.FileInfo], error)
	GetTransfer(context.Context, *connect.Request[v11.GetTransferRequest]) (*connect.Response[v11.Transfer], error)
	MakeDirectory(context.Context, *connect.Request[v11.MakeDirectoryRequest]) (*connect.Response[v11.MakeDirectoryResponse], error)
	Move(context.Context, *connect.Request[v11.MoveRequest]) (*connect.Response[v11.MoveResponse], error)
	Remove(context.Context, *connect.Request[v11.RemoveRequest]) (*connect.Response[v11.RemoveResponse], error)
	Import(context.Context, *connect.ClientStream[v11.ImportRequest]) (*connect.Response[v11.ImportResponse], error)
	Export(context.Context, *connect.Request[v11.ExportRequest], *connect.ServerStream[v11.ContentChunk]) error
}

